          if (ci == return_ci) {
            break;
          }
          ci = cipop(mrb);
          if (ci[1].cci != CINFO_NONE) {
            mrb_assert(prev_jmp != NULL);
            mrb->exc = (struct RObject*)break_new(mrb, RBREAK_TAG_BREAK, return_ci, v);
            mrb_gc_arena_restore(mrb, ai);
            mrb->c->vmexec = FALSE;
            mrb->jmp = prev_jmp;
            MRB_THROW(prev_jmp);
          }
