        if (mrb->c->status == MRB_TASK_CREATED) {
          mrb_gc_arena_restore(mrb, ai);
          mrb->jmp = prev_jmp;
          TASK_STOP(mrb);
          return v;
        }
#endif

        fiber_terminate(mrb, c, ci);
