/* Character classification function */
static inline uint8_t char_class(unsigned char c) {
  switch (c) {
    case '\0': return CHAR_NULL;
    case ' ':
    case '\t':
    case '\n':
    case '\v':
    case '\f':
    case '\r': return CHAR_SPACE;
    default: return 0;
  }
}
